{"concept":"An Arrakis desert nomad terminal forged from tempered bronze, glowing spice orange, and deep obsidian sand dunes.","fingerprint":"Cinzel, Spice Bronze, Obsidian Glass, Fremen Glyphs","needsHud":false,"hudReason":"","id":"8fc7976bfc0e","name":"Dune Arrakis Nomad Terminal","dark":true,"bg":"#0a0705","surface":"#1a120b","surface2":"#24180f","fg":"#f2d2a9","ink":"#ffffff","accent":"#e67e22","remapSurfaces":true,"customCss":"
:root{
 --m-bg:#0a0705;
 --m-surface:#1a120b;
 --m-surface2:#24180f;
 --m-fg:#f2d2a9;
 --m-ink:#ffffff;
 --m-accent:#e67e22;
 --m-rx:0deg;
 --m-ry:0deg;
}html, body{background:var(--m-bg)!important;color:var(--m-fg)!important;font-family:'Rajdhani',sans-serif!important;}/* Header */
header.mobile-topbar-header.cairo-settings-topbar{
 background:linear-gradient(135deg,var(--m-surface),var(--m-surface2))!important;
 border-bottom:2px solid var(--m-accent)!important;
 box-shadow:inset 0 -1px 0 var(--m-accent),0 4px 12px rgba(0,0,0,0.7)!important;
 position:relative;
}header.mobile-topbar-header.cairo-settings-topbar::after{
 content:'';
 position:absolute;bottom:-2px;left:10%;right:10%;height:2px;
 background:linear-gradient(90deg,transparent,var(--m-accent),transparent);
 animation:pulseGlow 3s ease-in-out infinite;
}
@keyframes pulseGlow{0%,100%{opacity:0.4;}50%{opacity:1;}}/* Search bar */
yt-searchbox.ytSearchboxComponentHost.ytSearchboxComponentMweb{
 background:var(--m-surface2)!important;
 border:1px solid var(--m-accent)!important;
 border-radius:6px!important;
 color:var(--m-fg)!important;
 transition:border-color .3s, box-shadow .3s;
}yt-searchbox.ytSearchboxComponentHost.ytSearchboxComponentMweb:focus-within{
 border-color:var(--m-ink)!important;
 box-shadow:0 0 12px var(--m-accent)!important;
 animation:searchPulse 1.5s ease-in-out infinite;
}
@keyframes searchPulse{0%,100%{box-shadow:0 0 12px var(--m-accent);}50%{box-shadow:0 0 24px var(--m-ink);}}/* Video cards */
ytm-video-with-context-renderer.item.adaptive-feed-item, [data-mydes="card"]{
 display:flex!important;
 flex-direction:column!important;
 width:100%!important;
 margin:0 0 16px 0!important;
 padding:16px!important;
 background:var(--m-surface)!important;
 border:2px solid var(--m-accent)!important;
 border-radius:8px!important;
 box-shadow:inset 0 0 14px rgba(230,126,34,0.15),0 6px 16px rgba(0,0,0,0.7)!important;
 transition:transform .2s ease, border-color .2s, box-shadow .2s;
}ytm-video-with-context-renderer.item.adaptive-feed-item:active, [data-mydes="card"]:active{
 transform:scale(0.98);
 border-color:var(--m-ink)!important;
 box-shadow:inset 0 0 14px rgba(230,126,34,0.3),0 8px 20px rgba(0,0,0,0.8)!important;
}
/* Title typography */
h3.media-item-headline,
[data-mydes="heading"]{
 font-family:'Cinzel',serif!important;
 text-transform:uppercase!important;
 letter-spacing:3px!important;
 color:var(--m-ink)!important;
 text-shadow:0 0 6px var(--m-accent),0 2px 4px rgba(0,0,0,0.8)!important;
 margin:0 0 8px 0!important;
}/* Buttons (only themed) */
[data-mydes="btn"]{
 background:linear-gradient(135deg,var(--m-accent),#c0661a)!important;
 color:var(--m-bg)!important;
 border:none!important;
 border-radius:4px!important;
 padding:8px 16px!important;
 font-family:'Rajdhani',sans-serif!important;
 font-weight:600!important;
 box-shadow:0 2px 8px rgba(230,126,34,0.5)!important;
 transition:box-shadow .2s, transform .1s;
}
[data-mydes="btn"]:active{transform:scale(0.96);box-shadow:0 4px 12px rgba(230,126,34,0.7)!important;}/* Bottom bar */
ytm-pivot-bar-renderer.frosted-glass{
 background:var(--m-surface)!important;
 border-top:2px solid var(--m-accent)!important;
 box-shadow:inset 0 1px 0 var(--m-accent),0 -4px 12px rgba(0,0,0,0.6)!important;
}
/* Global link color */
a{color:var(--m-fg)!important;text-decoration:none!important;}
a:focus{outline:2px solid var(--m-accent);outline-offset:2px;}

/* review */
header.mobile-topbar-header.cairo-settings-topbar { overflow: hidden !important; }","backdropHtml":"<svg viewBox="0 0 412 915" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="duneGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" stop-color="#1a120b"/><stop offset="40%" stop-color="#2b1d0f"/><stop offset="100%" stop-color="#0a0705"/></linearGradient><radialGradient id="spiceGlow" cx="50%" cy="30%" r="70%" fx="50%" fy="30%"><stop offset="0%" stop-color="#e67e22" stop-opacity="0.15"/><stop offset="100%" stop-color="#e67e22" stop-opacity="0"/></radialGradient><linearGradient id="windLines" x1="0%" y1="0%" x2="100%" y2="0%"><stop offset="0%" stop-color="#e67e22" stop-opacity="0.04"/><stop offset="50%" stop-color="#f2d2a9" stop-opacity="0.02"/><stop offset="100%" stop-color="#e67e22" stop-opacity="0.04"/></linearGradient></defs><rect width="412" height="915" fill="url(#duneGrad)"/><rect width="412" height="915" fill="url(#spiceGlow)"/><!-- wind current lines --><g stroke="url(#windLines)" stroke-width="0.5" fill="none" opacity="0.6"><line x1="0" y1="150" x2="412" y2="150"/><line x1="0" y1="300" x2="412" y2="300"/><line x1="0" y1="450" x2="412" y2="450"/><line x1="0" y1="600" x2="412" y2="600"/><line x1="0" y1="750" x2="412" y2="750"/></g><!-- drifting spice motes --><g fill="#e67e22" opacity="0.7"><circle cx="50" cy="200" r="2"><animate attributeName="cy" from="200" to="800" dur="30s" repeatCount="indefinite"/><animate attributeName="cx" from="50" to="360" dur="28s" repeatCount="indefinite"/></circle><circle cx="180" cy="350" r="1.5"><animate attributeName="cy" from="350" to="950" dur="35s" repeatCount="indefinite"/><animate attributeName="cx" from="180" to="400" dur="33s" repeatCount="indefinite"/></circle><circle cx="300" cy="100" r="2.5"><animate attributeName="cy" from="100" to="850" dur="27s" repeatCount="indefinite"/><animate attributeName="cx" from="300" to="380" dur="30s" repeatCount="indefinite"/></circle><circle cx="120" cy="500" r="1"><animate attributeName="cy" from="500" to="950" dur="40s" repeatCount="indefinite"/><animate attributeName="cx" from="120" to="350" dur="38s" repeatCount="indefinite"/></circle></g></svg>","hudHtml":"","customJs":"MydesBridge.decorateUnits('ytm-video-with-context-renderer.item.adaptive-feed-item, [data-mydes="card"]', '<svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg" width="64" height="64"><defs><linearGradient id="octGlow" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#e67e22"/><stop offset="100%" stop-color="#f2d2a9"/></linearGradient></defs><path d="M4 0h56l4 4v56l-4 4H4L0 60V4L4 0z" fill="none" stroke="url(#octGlow)" stroke-width="2" stroke-linejoin="round"/></svg>'); MydesBridge.injectOrnament('header.mobile-topbar-header.cairo-settings-topbar', '<svg viewBox="0 0 120 30" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="crestGrad" x1="0%" y1="0%" x2="100%" y2="0%"><stop offset="0%" stop-color="#e67e22"/><stop offset="100%" stop-color="#f2d2a9"/></linearGradient></defs><polygon points="60,0 120,30 0,30" fill="url(#crestGrad)" opacity="0.85"/><polygon points="60,5 115,28 5,28" fill="#0a0705"/></svg>', "append"); MydesBridge.spawnParticles({mode:"float", colors:["#0a0705","#f2d2a9","#e67e22"], count:35, speed:1.0}); MydesBridge.enable3DTilt(8);"}

